band_hsd:
Geometry = GenFormat {
  <<< "geo.gen"
}
Hamiltonian = DFTB {
  SCC = Yes
  SCCTolerance = 1e-10
  MaxSCCIterations = 1
  ShellResolvedSCC = No
  ReadInitialCharges = Yes
  ConvergentSCCOnly = No
  Charge = 0.0
  SlaterKosterFiles = Type2FileNames {
    Prefix = "/tmp/pydftb_ref_h3xss_cg/plain/"
    Separator = "-"
    Suffix = ".skf"
  }
  MaxAngularMomentum {
    Cu = "d"
  }
  Filling = Fermi {
    Temperature [K] = 1000.0
  }
  KPointsAndWeights = Klines {
    1 0.0 0.0 0.0
    10 0.5 0.0 0.5
    5 0.5 0.25 0.75
    7 0.5 0.5 0.5
    9 0.0 0.0 0.0
    10 0.375 0.375 0.75
  }
  EwaldTolerance = 1e-12

}
Analysis {
  PrintForces = Yes
  MullikenAnalysis = Yes
}
Options {
  WriteDetailedOut = Yes
  WriteResultsTag = Yes
  TimingVerbosity = 0
}
ParserOptions {
  ParserVersion = 14
}
Parallel {
  UseOmpThreads = Yes
}
